const monthly=$('#monthly-chart'),m=D.monthly,bottom=296,top=35,left=60,right=1044,step=(right-left)/m.length,maxCount=Math.ceil(Math.max(...m.map(r=>r.count))/5)*5,maxMedian=Math.ceil(Math.max(...m.map(r=>r.median||0))/10000)*10000;
