const countNodes=document.querySelectorAll('[data-count]');function count(n){if(n.dataset.counted)return;n.dataset.counted='1';const v=Number(n.dataset.count),dec=Number(n.dataset.decimals||0);if(motionOff){n.textContent=v.toFixed(dec);return;}const began=performance.now();function frame(t){const p=Math.min(1,(t-began)/1100);n.textContent=(v*(1-Math.pow(1-p,3))).toFixed(dec);if(p<1&&!motionOff)requestAnimationFrame(frame);else n.textContent=v.toFixed(dec);}requestAnimationFrame(frame);}
const obs=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');e.target.querySelectorAll('[data-count]').forEach(count);if(e.target.hasAttribute('data-count'))count(e.target);obs.unobserve(e.target);}}),{threshold:.12});document.querySelectorAll('[data-reveal],[data-count]').forEach(n=>obs.observe(n));
